"""The agent under test, generated by Inspect's active model.

``InspectAgent`` is a drop-in for the native ``LiteLLMAgent`` under the native
``Orchestrator``: same ``add_assistant_message`` / ``add_user_message`` /
``respond`` contract, same ``AgentResponse``. It only generates; the
orchestrator executes the tools through ``ToolKit``, so the tools are offered
as ``ToolInfo`` definitions and Inspect never runs them.
"""
from __future__ import annotations

import json
from contextvars import ContextVar
from typing import Any

from inspect_ai.model import (
    ChatMessage,
    ChatMessageAssistant,
    ChatMessageSystem,
    ChatMessageTool,
    ChatMessageUser,
    GenerateConfig,
    Model,
    ModelOutput,
    ModelRefusalError,
)
from inspect_ai.model._generate_config import active_generate_config
from inspect_ai.model._model import ModelGenerateError
from inspect_ai.tool import ToolInfo, ToolParams

from tau_rec.agents.base import AgentResponse, BaseAgent
from tau_rec.agents.request_settings import agent_request_settings, native_model_name
from tau_rec.harness import LEGACY, HarnessProfile
from tau_rec.inspect_support.config import fill_unset


class AgentContextLengthError(Exception):
    """The model ran out of context (``stop_reason="model_length"``).

    The message contains "context length", so the orchestrator stops the trial
    as a context stop (``TIMEOUT`` under the legacy harness), as it does for
    litellm's context-window error on the native path.
    """


class AgentCallError(Exception):
    """An agent call native would not have turned into a usable turn.

    Raised for a content-filter stop and for a tool call whose arguments did
    not parse. The trial errors; it never becomes an agent message or a
    ``{}``-argument tool call (which, for ``recommend``, would be an abstention).

    The message is fixed text only. The orchestrator classifies errors by
    substring ("context" + "length" is a context stop), so model-generated
    text (raw arguments, tool names, call ids) is kept on attributes instead.
    """

    def __init__(
        self,
        message: str,
        *,
        tool_call_id: str | None = None,
        function: str | None = None,
        parse_error: str | None = None,
    ) -> None:
        super().__init__(message)
        self.tool_call_id = tool_call_id
        self.function = function
        self.parse_error = parse_error


class AgentProviderError(Exception):
    """An Inspect provider error, re-raised with no request or model text.

    Inspect's ``ModelGenerateError`` message embeds up to 200 lines of the
    request JSON (the system prompt and every turn). The orchestrator
    substring-matches "context" + "length" on ``str(error)`` to detect a
    context stop, so request text would let a conversation that mentions
    "context length" end the trial as a ``TIMEOUT`` instead of erroring it.
    The message keeps only the HTTP status or, when there is none, the
    provider exception's class name (code-defined text). The provider's own
    message is kept on ``provider_message``; the original error is chained
    as ``__cause__``.
    """

    def __init__(
        self,
        message: str,
        *,
        status_code: int | None = None,
        provider_message: str | None = None,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.provider_message = provider_message


def _provider_error(error: ModelGenerateError) -> AgentProviderError:
    if error.status_code is not None:
        detail = f"status {int(error.status_code)}"
    else:
        cause = error.__cause__
        detail = type(cause).__name__ if cause is not None else "no status"
    return AgentProviderError(
        f"agent provider call failed ({detail})",
        status_code=error.status_code,
        provider_message=error.provider_message,
    )


# Raw provider responses, captured per respond() call. A context-local holder
# keeps concurrent samples sharing one (memoized) Model apart.
_raw_capture: ContextVar[list[Any] | None] = ContextVar("tau_rec_raw_capture", default=None)


def _install_raw_capture(model: Model) -> None:
    """Record the ``ModelCall`` each successful ``ModelAPI.generate`` returns.

    The transcript's ``ModelEvent.call`` is not usable for this: by default
    Inspect keeps it only for the first few calls per model, and
    ``--no-log-model-api`` drops it. Wrapping the API instance's ``generate``
    sees every attempt; outside a ``respond`` it only passes through.
    """
    api = model.api
    if getattr(api, "_tau_rec_raw_capture", False):
        return
    original = api.generate

    async def generate(*args: Any, **kwargs: Any) -> Any:
        result = await original(*args, **kwargs)
        holder = _raw_capture.get()
        if holder is not None:
            holder[:] = [
                result[1]
                if isinstance(result, tuple) and isinstance(result[0], ModelOutput)
                else None
            ]
        return result

    api.generate = generate  # type: ignore[method-assign]
    api._tau_rec_raw_capture = True  # type: ignore[attr-defined]


def _raw_arguments(response: Any) -> dict[str, str]:
    """Tool-call id -> raw argument string, from an OpenAI-shaped response body.

    Covers Chat Completions (``choices[].message.tool_calls[]``) and Responses
    (``output[]`` items of type ``function_call``). Any other shape yields {}.
    """
    found: dict[str, str] = {}
    if not isinstance(response, dict):
        return found
    for choice in response.get("choices") or []:
        message = choice.get("message") if isinstance(choice, dict) else None
        for call in (message or {}).get("tool_calls") or []:
            if not isinstance(call, dict):
                continue
            function = call.get("function") or {}
            if isinstance(call.get("id"), str) and isinstance(function.get("arguments"), str):
                found[call["id"]] = function["arguments"]
    for item in response.get("output") or []:
        if (
            isinstance(item, dict)
            and item.get("type") == "function_call"
            and isinstance(item.get("call_id"), str)
            and isinstance(item.get("arguments"), str)
        ):
            found[item["call_id"]] = item["arguments"]
    return found


def _native_arguments(raw: str, call_id: str, function: str) -> dict:
    """Parse raw arguments exactly as native does (``json.loads``), requiring a dict."""
    try:
        arguments = json.loads(raw)
    except (json.JSONDecodeError, RecursionError):
        arguments = None
    else:
        if isinstance(arguments, dict):
            return arguments
    raise AgentCallError(
        "agent tool call arguments are not a JSON object",
        tool_call_id=call_id,
        function=function,
        parse_error="arguments did not json.loads to an object",
    )


def tool_infos(tool_definitions: list[dict]) -> list[ToolInfo]:
    """The OpenAI-format tool definitions as Inspect ``ToolInfo``.

    ``additionalProperties`` is set to ``None`` so Inspect does not add
    ``additionalProperties: false``, which the native definitions do not send.
    """
    infos = []
    for definition in tool_definitions:
        function = definition["function"]
        parameters = dict(function.get("parameters") or {})
        parameters.setdefault("additionalProperties", None)
        infos.append(
            ToolInfo(
                name=function["name"],
                description=function.get("description", ""),
                parameters=ToolParams.model_validate(parameters),
            )
        )
    return infos


class InspectAgent(BaseAgent):
    def __init__(
        self,
        model: Model,
        system_prompt: str,
        tool_definitions: list[dict],
        harness: HarnessProfile = LEGACY,
    ) -> None:
        self._model = model
        self._system_prompt = system_prompt
        self._tools = tool_infos(tool_definitions)
        self._harness = harness
        self._history: list[ChatMessage] = []
        _install_raw_capture(model)

    def reset(self) -> None:
        self._history = []

    def add_user_message(self, content: str) -> None:
        self._history.append(ChatMessageUser(content=content))

    def add_assistant_message(self, content: str) -> None:
        """Inject a pre-generated assistant message (the opening greeting)."""
        self._history.append(ChatMessageAssistant(content=content))

    def _generate_config(self) -> GenerateConfig:
        # Explicit = what the user set on the model (its own config, e.g. from
        # a role or eval-retry) and for the run (--temperature etc.). Inspect
        # merges the same two for the active model; the mirrored native
        # settings fill only what both leave unset.
        explicit = self._model.config.merge(active_generate_config())
        mirrored = agent_request_settings(
            # str(model) is the provider-qualified name ("openai/gpt-5-mini");
            # model.name lacks the provider prefix.
            native_model_name(str(self._model)),
            explicit.reasoning_effort,
            self._harness,
        )
        return fill_unset(mirrored, explicit)

    def _tool_messages(self, tool_results: list[dict]) -> list[ChatMessageTool]:
        functions = {
            call.id: call.function
            for message in self._history
            if isinstance(message, ChatMessageAssistant)
            for call in (message.tool_calls or [])
        }
        return [
            ChatMessageTool(
                content=result["content"],
                tool_call_id=result["tool_call_id"],
                function=functions.get(result["tool_call_id"]),
            )
            for result in tool_results
        ]

    async def respond(self, tool_results: list[dict] | None = None) -> AgentResponse:
        if tool_results:
            # Track tool results in history so future calls see them.
            self._history.extend(self._tool_messages(tool_results))

        holder: list[Any] = []
        token = _raw_capture.set(holder)
        try:
            output = await self._model.generate(
                [ChatMessageSystem(content=self._system_prompt), *self._history],
                tools=self._tools,
                config=self._generate_config(),
            )
        except ModelGenerateError as error:
            raise _provider_error(error) from error
        except ModelRefusalError as error:
            # fail_on_refusal is set: same outcome as a content_filter stop.
            raise AgentCallError(
                "agent call was stopped by the provider's content filter "
                "(stop_reason=content_filter, fail_on_refusal)"
            ) from error
        finally:
            _raw_capture.reset(token)
        _check_stop(output)

        call = holder[0] if holder else None
        raw = _raw_arguments(getattr(call, "response", None))

        message = output.message
        tool_calls = []
        for tool_call in message.tool_calls or []:
            if tool_call.parse_error is not None:
                # Native json.loads raises here; never pass on {} arguments.
                raise AgentCallError(
                    "agent tool call arguments could not be parsed",
                    tool_call_id=tool_call.id,
                    function=tool_call.function,
                    parse_error=tool_call.parse_error,
                )
            if tool_call.id in raw:
                # Inspect parses leniently (YAML for non-object strings, stray
                # quote recovery), so "" or "null" can become {"item_id": None},
                # an abstention. Re-parse the raw text as native does.
                arguments = _native_arguments(raw[tool_call.id], tool_call.id, tool_call.function)
            else:
                # No raw response for this call (a provider whose response is
                # not OpenAI-shaped, a cache hit, mockllm): fall back to
                # Inspect's parsed arguments. Documented deviation.
                arguments = tool_call.arguments
            tool_calls.append(
                {"id": tool_call.id, "name": tool_call.function, "arguments": arguments}
            )

        # Kept as returned, so reasoning blocks round-trip on later turns.
        self._history.append(message)
        return AgentResponse(message=message.text or None, tool_calls=tool_calls)


def _check_stop(output: ModelOutput) -> None:
    """Map Inspect stop reasons the native path would raise on."""
    if output.stop_reason == "model_length":
        raise AgentContextLengthError(
            f"agent model exceeded its context length (stop_reason=model_length"
            f"{': ' + output.error if output.error else ''})"
        )
    if output.stop_reason == "content_filter":
        # Fixed text: the refusal itself is model text and stays out.
        raise AgentCallError(
            "agent call was stopped by the provider's content filter "
            "(stop_reason=content_filter)"
        )
    # "max_tokens" passes through, as on the native path.
